/* MODULE ob03 · Bước 1 Quan sát · Ngành hàng (category) và luật chơi của nó
   10 bài × 7 câu. Thương hiệu được nêu như ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'ob03', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:ob03-01', skill:'insight', read:'6 phút', t:'Hãng nước suối của bạn đang cạnh tranh với ai?',
  situation:'Bạn làm marketing cho một hãng nước suối đóng chai 500 ml, giá 6.000 đồng. Sếp hỏi: đối thủ của mình là ai? Cả nhóm liệt kê ba hãng nước suối khác. Nhưng khi đứng ở tủ mát cửa hàng tiện lợi, bạn thấy khách cầm chai nước suối lên rồi đặt xuống, chọn trà đóng chai hoặc nước điện giải cùng tầm giá 10.000 đồng.',
  concept:{ name:'Định nghĩa ngành hàng theo nhu cầu',
    body:'Ngành hàng không phải danh mục trong sổ kế toán mà là <b>tập hợp những thứ khách coi là thay thế được cho nhau</b> để giải quyết cùng một nhu cầu trong cùng một hoàn cảnh. Định nghĩa theo sản phẩm (nước suối) chỉ cho thấy đối thủ trông giống mình; định nghĩa theo nhu cầu (giải khát nhanh khi đang đi đường) cho thấy cả trà, nước điện giải. Chọn mức vừa phải: giữ chung hoàn cảnh mua và tầm giá, bỏ những thứ khách không bao giờ cầm lên cân nhắc cùng nhau. Kiểm tra bằng hành vi, không bằng suy luận: hỏi khách ngay tại tủ mát "nếu hết nước suối, bạn lấy gì?", hoặc xem lượt mua đổi ra sao khi một bên đổi giá. Thứ nào được nêu tên nhiều thì nằm trong ngành.' },
  example:'Nhóm đếm 100 lượt khách ở tủ mát trong một buổi chiều (số minh hoạ): 30 mua nước suối, 25 trà đóng chai, 20 nước điện giải, 25 nước ngọt có ga. Chỉ tính ngành nước suối, hãng bạn chiếm 12 trên 30 lượt, tức 40%. Tính theo nhu cầu giải khát, 12 trên 100 chỉ là 12%. Nhóm hỏi thêm 30 khách "nếu hết nước suối bạn lấy gì?": 18 người nêu trà hoặc nước điện giải. Khách rời nước suối vì muốn có vị, nên hướng đi là thêm vị chứ không phải giảm giá đánh ba hãng nước suối.',
  takeaway:'Đối thủ là bất cứ thứ gì khách sẵn sàng chọn thay bạn cho cùng một nhu cầu.',
  apply:'Chọn một sản phẩm bạn mua hôm nay. Nói trong 60 giây: nếu nó hết hàng, bạn sẽ mua gì thay? Danh sách đó chính là ngành hàng thật.',
  mistakes:['Liệt kê đối thủ chỉ là những hãng có sản phẩm trông giống mình.','Định nghĩa ngành quá rộng như "đồ uống" nên không rút ra được hành động nào.'],
  q:[
  { type:'mcq', stem:'Đoán trước: với một chai nước suối 6.000 đồng ở cửa hàng tiện lợi, đối thủ nguy hiểm nhất nhiều khả năng là gì?',
    options:[{k:'a',t:'Một hãng nước suối khác bán rẻ hơn 1.000 đồng'},{k:'b',t:'Đồ uống đóng chai khác cùng tủ mát, cùng tầm giá'},
             {k:'c',t:'Máy lọc nước gia đình vì tính ra mỗi lít rẻ hơn rất nhiều lần'},{k:'d',t:'Quán cà phê gần cửa hàng vì có chỗ ngồi mát'}],
    answer:'b', why:{a:'Có cạnh tranh, nhưng khách ở tủ mát thường không dò chênh 1.000 đồng giữa các hãng nước suối.',
      b:'Đúng. Cùng hoàn cảnh (khát, đang đi đường) và cùng tủ mát, khách đổi qua lại dễ nhất.',
      c:'Máy lọc giải quyết nhu cầu uống ở nhà, không phải lúc đang ở ngoài đường.',
      d:'Quán cà phê là hoàn cảnh khác: ngồi lại, thời gian dài, giá cao hơn nhiều.'} },
  { type:'mcq', stem:'Số liệu cho thấy khách bỏ nước suối để chọn trà đóng chai vì muốn có vị. Với ngân sách có hạn, bạn chọn gì?',
    options:[{k:'a',t:'Giảm giá 1.000 đồng để giành khách từ ba hãng nước suối'},{k:'b',t:'Tăng quảng cáo nhấn mạnh nguồn nước tinh khiết của hãng'},
             {k:'c',t:'Thử một dòng nước suối có vị nhẹ, không đường, cùng giá'},{k:'d',t:'Mở rộng sang bán bình 20 lít cho văn phòng và hộ gia đình'}],
    answer:'c', why:{a:'Đánh giá vào ba hãng nước suối là đánh vào mảnh nhỏ; khách uống trà không quay lại vì rẻ hơn 1.000 đồng.',
      b:'Tinh khiết là lý do chọn giữa các hãng nước suối, không phải lý do để bỏ trà quay về.',
      c:'Đúng. Nó trả lời đúng nhu cầu khiến khách rời đi (muốn có vị) mà vẫn giữ lợi thế không đường.',
      d:'Bình 20 lít là nhu cầu khác, hoàn cảnh khác; không giải quyết việc mất khách ở tủ mát.'} },
  { type:'calc', stem:'Trong 200 lượt mua đồ uống ở tủ mát, 60 lượt là nước suối, trong đó hãng bạn có 24 lượt. Thị phần của bạn tính theo ngành "giải khát tại tủ mát" là bao nhiêu phần trăm?',
    unit:'%', ans:12, tol:0.1, wrong:[[40,'SAI_MAU_SO'],[30,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Mẫu số là toàn bộ lượt mua giải khát: 200.','24 ÷ 200 = 0,12 = <b>12%</b>. (Tính 24 ÷ 60 = 40% là thị phần trong riêng nước suối.)'] },
  { type:'mcq', stem:'Cách kiểm tra nào cho biết hai sản phẩm có thật sự cùng một ngành hàng hay không?',
    options:[{k:'a',t:'Chúng được xếp chung một khu trong siêu thị'},{k:'b',t:'Chúng có thành phần và công nghệ sản xuất gần nhau'},
             {k:'c',t:'Chúng cùng một tập đoàn sở hữu và một nhà phân phối'},{k:'d',t:'Khách đổi qua lại giữa chúng khi giá của một bên đổi'}],
    answer:'d', why:{a:'Cách xếp kệ theo logic kho vận của siêu thị, không phải theo lựa chọn của khách.',
      b:'Sản phẩm khác hẳn nhau vẫn có thể thay thế nhau nếu cùng giải quyết một nhu cầu.',
      c:'Chủ sở hữu không quyết định khách coi gì là thay thế.',
      d:'Đúng. Khách đổi qua lại khi giá đổi là bằng chứng họ coi hai thứ thay thế được.'} },
  { type:'mcq', stem:'Một hãng cà phê hoà tan định nghĩa ngành của mình là "mọi thứ giúp người ta tỉnh táo". Vấn đề của định nghĩa này là gì?',
    options:[{k:'a',t:'Quá rộng, gồm cả ngủ trưa và thể thao, nên không chỉ ra hành động'},{k:'b',t:'Quá hẹp, vì bỏ sót cà phê pha phin và cà phê chuỗi'},
             {k:'c',t:'Sai, vì cà phê hoà tan chỉ cạnh tranh với cà phê hoà tan'},{k:'d',t:'Hợp lý, vì định nghĩa càng rộng thì càng thấy thêm nhiều cơ hội tăng trưởng mới'}],
    answer:'a', why:{a:'Đúng. Khi mọi thứ là đối thủ, không biết nên đánh vào đâu; cần gắn với hoàn cảnh cụ thể như buổi sáng vội ở văn phòng.',
      b:'Định nghĩa này đã bao gồm các loại cà phê kia; vấn đề là nó bao quá nhiều.',
      c:'Cà phê hoà tan rõ ràng cạnh tranh với phin, chuỗi, nước tăng lực trong nhiều hoàn cảnh.',
      d:'Rộng hơn không có nghĩa tốt hơn; quá rộng thì không còn là công cụ ra quyết định.'} },
  { type:'mcq', stem:'Một chuỗi bánh mì văn phòng thấy doanh số buổi sáng giảm khi một ứng dụng giao đồ ăn tung mã giảm giá xôi và cơm tấm. Nên hiểu ngành hàng của chuỗi thế nào?',
    options:[{k:'a',t:'Chỉ là bánh mì, việc xôi giảm giá là chuyện ngoài ngành'},{k:'b',t:'Là ngành giao đồ ăn, nên chuỗi phải tự làm ứng dụng riêng để giữ khách'},
             {k:'c',t:'Là bữa sáng nhanh cho dân văn phòng, gồm cả xôi và cơm tấm'},{k:'d',t:'Là đồ ăn nói chung, kể cả cơm tối cho gia đình'}],
    answer:'c', why:{a:'Doanh số giảm đúng lúc xôi giảm giá cho thấy khách coi chúng thay thế nhau.',
      b:'Ứng dụng giao đồ là kênh, không phải ngành hàng.',
      c:'Đúng. Cùng nhu cầu (ăn sáng nhanh), cùng khách, cùng khung giờ: đó là ngành thật.',
      d:'Quá rộng; bữa tối gia đình không cạnh tranh với ổ bánh mì 7 giờ sáng.'} },
  { type:'mcq', stem:'Tình huống mới: một hãng sữa hạt thấy doanh số tăng mạnh nhưng thị phần trong "ngành sữa hạt" lại giảm. Giải thích nào hợp lý nhất?',
    options:[{k:'a',t:'Số liệu có lỗi, vì doanh số tăng thì thị phần trong ngành cũng phải tăng theo'},{k:'b',t:'Ngành sữa hạt tăng nhanh hơn hãng, nên hãng lớn chậm hơn ngành'},
             {k:'c',t:'Hãng đang tăng giá nên doanh số lên nhưng khách giảm'},{k:'d',t:'Đối thủ đã rời ngành sữa hạt và chuyển sang sữa bò'}],
    answer:'b', why:{a:'Thị phần là tỉ lệ; hãng tăng 10% mà ngành tăng 25% thì thị phần vẫn giảm.',
      b:'Đúng. Đây là cảnh báo: ngành đang mở rộng mà hãng không theo kịp.',
      c:'Có thể, nhưng dữ kiện không nói gì về giá; và điều đó không giải thích thị phần giảm.',
      d:'Nếu đối thủ rời ngành, thị phần của hãng phải tăng chứ không giảm.'} },
  ]},

/* ------------------------------------------------------------------ 02 */
{ id:'B:ob03-02', skill:'measure', read:'7 phút', t:'Ngành to hay ngành đang lớn — nên vào đâu?',
  situation:'Một startup đồ uống cân nhắc hai ngành. Ngành A là nước ngọt có ga: quy mô khoảng 20.000 tỉ đồng một năm, tăng 2%. Ngành B là nước uống lên men có lợi cho đường ruột: quy mô 1.000 tỉ, tăng 30% mỗi năm. Nhà đầu tư muốn biết: nếu năm tới giành được phần tăng thêm của ngành, bên nào cho nhiều tiền hơn?',
  concept:{ name:'Quy mô và tăng trưởng ngành',
    body:'Hai con số đầu tiên cần đọc về một ngành là <b>quy mô</b> (tổng tiền khách chi mỗi năm) và <b>tăng trưởng</b> (ngành to thêm bao nhiêu phần trăm). Ngành to nhưng đứng yên thì mỗi đồng của bạn phải giật từ người khác, và người dẫn đầu sẽ phản đòn. Ngành nhỏ tăng nhanh có tiền mới đổ vào mỗi năm, từ khách chưa quen hãng nào. Nhưng quy mô chưa phải lãi: nghiên cứu hành vi mua (quy luật Double Jeopardy, Ehrenberg – Sharp) nhắc rằng hãng nhỏ luôn ít khách và ít được mua lại, nên phần giành được tuỳ độ phủ và độ nhận biết của bạn. Phép tính đủ là <b>tiền tuyệt đối tăng thêm</b> × phần giành được × biên gộp, rồi hỏi tăng trưởng này bền hay chỉ là cơn sốt.' },
  example:'Ngành A tăng 2% của 20.000 tỉ = 400 tỉ tiền mới. Ngành B tăng 30% của 1.000 tỉ = 300 tỉ. Nhìn tuyệt đối, A nhiều hơn. Nhưng phần giành được mới quyết định, và đó là một giả định cần thử độ nhạy. Giành 1% phần tăng ở A là 4 tỉ; để có 4 tỉ ở B chỉ cần khoảng 1,3%. Nếu hãng lớn ở A phủ kín kênh nên bạn chỉ giành 0,5% (2 tỉ), còn ở B giành 5% (15 tỉ) thì B hơn xa. Ngược lại, nếu ở B các hãng ngoại vào ào ạt và bạn chỉ giành 1% (3 tỉ) thì B thua A. Các tỉ lệ giành được ở đây đều là giả định minh hoạ; việc của bạn là tìm bằng chứng cho từng giả định trước khi chọn.',
  takeaway:'Quy tăng trưởng ra tiền tuyệt đối, rồi hỏi mình giành được bao nhiêu phần trong đó.',
  apply:'Chọn một ngành bạn quan tâm, tìm một con số quy mô và một con số tăng trưởng công khai. Nói trong 60 giây: mỗi năm có bao nhiêu tiền mới đổ vào ngành này?',
  mistakes:['So sánh tỉ lệ tăng trưởng mà quên quy ra số tiền tuyệt đối.','Chọn ngành to nhất mà không hỏi mình giành được phần nào trong đó.'],
  q:[
  { type:'mcq', stem:'Đoán trước: startup nhỏ, ít vốn phân phối, nên ưu tiên ngành nào trong hai ngành trên?',
    options:[{k:'a',t:'Ngành A vì quy mô gấp 20, giành một mẩu nhỏ là đủ sống'},{k:'b',t:'Ngành A vì tăng chậm nghĩa là ổn định, ít rủi ro hơn'},
             {k:'c',t:'Không vào ngành nào, vì cả hai đều đã có hãng lớn'},{k:'d',t:'Ngành B vì phần tăng thêm đến từ khách chưa trung thành'}],
    answer:'d', why:{a:'"Một mẩu nhỏ của ngành lớn" là ảo giác phổ biến; mẩu nhỏ đó phải giật từ hãng lớn đang phủ kín kênh.',
      b:'Ổn định cho hãng đã có chỗ, không cho người mới vào.',
      c:'Ngành nào cũng có hãng lớn; câu hỏi là ở đâu người mới dễ giành phần tăng thêm.',
      d:'Đúng. Ngành tăng nhanh có khách mới mỗi năm, người mới cạnh tranh ngang hàng hơn.'} },
  { type:'mcq', stem:'Nhà đầu tư chỉ đưa bạn một con số: "ngành B tăng 30%". Trước khi kết luận, bạn làm gì?',
    options:[{k:'a',t:'Tin ngay vì 30% là tốc độ rất cao so với cả thị trường'},{k:'b',t:'Hỏi quy mô gốc để quy ra số tiền tăng thêm mỗi năm'},
             {k:'c',t:'Hỏi xem ngành đã tăng 30% được bao nhiêu tháng liên tục'},{k:'d',t:'So ngay với tăng trưởng GDP để xem ngành có vượt không'}],
    answer:'b', why:{a:'30% của 10 tỉ và 30% của 10.000 tỉ là hai câu chuyện khác nhau.',
      b:'Đúng. Không có quy mô gốc thì tỉ lệ không nói được có bao nhiêu tiền mới.',
      c:'Độ bền cũng quan trọng, nhưng câu đầu tiên vẫn là: 30% của bao nhiêu?',
      d:'So với GDP cho biết ngành nóng hay không, không cho biết tiền mới nhiều hay ít.'} },
  { type:'calc', stem:'Ngành B quy mô 1.000 tỉ đồng, tăng 30% năm tới. Nếu startup giành được 10% phần tăng thêm, doanh số mới là bao nhiêu tỉ đồng?',
    unit:'tỉ đồng', ans:30, tol:0.1, wrong:[[100,'SAI_MAU_SO'],[130,'NHAM_SO_TUYET_DOI']], errors:['SAI_MAU_SO','NHAM_SO_TUYET_DOI'],
    steps:['Phần tăng thêm: 1.000 × 30% = 300 tỉ.','Phần giành được: 300 × 10% = <b>30 tỉ</b>. (100 là 10% của cả ngành, không phải của phần tăng thêm.)'] },
  { type:'mcq', stem:'Giả sử biên gộp ngành A là 25% (hãng lớn quen kênh, giá ổn định), ngành B chỉ 10% (số minh hoạ; phải trả phí kênh và giảm giá kéo khách mới). Startup giành được 4 tỉ doanh số ở A hoặc 30 tỉ ở B. Bên nào cho lãi gộp nhiều hơn?',
    options:[{k:'a',t:'A, vì biên 25% cao hơn gấp 2,5 lần biên của B'},{k:'b',t:'A, vì ngành lớn có khách mua đều nên ít rủi ro hơn'},
             {k:'c',t:'B, vì 30 tỉ × 10% = 3 tỉ, so với 1 tỉ lãi gộp ở A'},{k:'d',t:'Hoà nhau, vì biên cao ở A bù cho doanh số thấp hơn'}],
    answer:'c', why:{a:'Biên cao hơn nhưng doanh số nhỏ hơn 7,5 lần: 4 tỉ × 25% chỉ được 1 tỉ.',
      b:'Ổn định là chuyện rủi ro, không làm ra thêm lãi: A vẫn chỉ cho 1 tỉ lãi gộp.',
      c:'Đúng. 30 × 10% = 3 tỉ, gấp 3 lần 1 tỉ ở A. Nhìn doanh số hay nhìn biên riêng lẻ đều dễ sai.',
      d:'Không bù đủ: 1 tỉ so với 3 tỉ, chênh gấp ba.'} },
  { type:'mcq', stem:'Tình huống mới: ngành trà sữa đóng chai quy mô 3.000 tỉ, tăng 5%; ngành cà phê lon quy mô 500 tỉ, tăng 40%. Phát biểu nào đúng?',
    options:[{k:'a',t:'Cà phê lon có nhiều tiền mới hơn vì tăng gấp 8 lần'},{k:'b',t:'Trà sữa có 150 tỉ tiền mới, cà phê lon có 200 tỉ'},
             {k:'c',t:'Hai ngành có tiền mới bằng nhau vì quy mô bù trừ tỉ lệ'},{k:'d',t:'Trà sữa có nhiều tiền mới hơn vì quy mô gấp 6 lần'}],
    answer:'b', why:{a:'Kết luận đúng hướng nhưng lý do sai: phải quy ra tiền, không so tỉ lệ.',
      b:'Đúng. 3.000 × 5% = 150 tỉ; 500 × 40% = 200 tỉ.',
      c:'Tính ra 150 và 200, không bằng nhau.',
      d:'Quy mô to hơn không đủ; tỉ lệ tăng thấp làm tiền mới ít hơn.'} },
  { type:'mcq', stem:'Một báo cáo nói "ngành mỹ phẩm online tăng 50%". Điều gì cần kiểm tra để khỏi hiểu sai?',
    options:[{k:'a',t:'Tăng là do khách mới hay do khách chuyển từ cửa hàng sang'},{k:'b',t:'Báo cáo có được đăng trên một trang tin lớn hay không'},
             {k:'c',t:'Tên các thương hiệu được nhắc đến nhiều nhất trong báo cáo'},{k:'d',t:'Báo cáo dùng biểu đồ cột hay biểu đồ đường để trình bày'}],
    answer:'a', why:{a:'Đúng. Nếu chỉ là khách chuyển kênh, tổng ngành mỹ phẩm có thể không đổi; đó là thay đổi kênh chứ không phải tiền mới.',
      b:'Nơi đăng không thay đổi việc con số đo cái gì.',
      c:'Tên hãng không trả lời được tăng trưởng từ đâu ra.',
      d:'Cách vẽ không đổi bản chất số liệu.'} },
  { type:'mcq', stem:'Ngành đang tăng 30% năm nay. Rủi ro nào người mới hay bỏ qua?',
    options:[{k:'a',t:'Ngành tăng nhanh thì không có đối thủ nào đáng lo'},{k:'b',t:'Hãng vào muộn một năm sẽ không còn khách nào để giành trong ngành nữa'},
             {k:'c',t:'Ngành tăng nhanh thì giá bán sẽ tăng theo hằng năm'},{k:'d',t:'Tốc độ có thể là cơn sốt và hạ nhanh khi hết mới lạ'}],
    answer:'d', why:{a:'Ngành nóng hút rất nhiều người mới vào cùng lúc.',
      b:'Không có quy luật nào như vậy; nhiều ngành chỉ nóng một hai năm.',
      c:'Ngành nóng nhiều người vào thường làm giá giảm chứ không tăng.',
      d:'Đúng. Cần hỏi: khách mua lại không, hay chỉ thử một lần vì tò mò?'} },
  ]},

/* ------------------------------------------------------------------ 03 */
{ id:'B:ob03-03', skill:'measure', read:'7 phút', t:'Khách mua bao lâu một lần, mỗi lần bao nhiêu?',
  situation:'Bạn so hai ngành để chọn nơi làm việc: dầu gội và nồi chiên không dầu. Cả hai đều có khách chi khoảng 1,2 triệu đồng một năm. Nhưng khách mua dầu gội 12 lần một năm, mỗi lần 100.000 đồng; còn nồi chiên thì cứ ba năm mới mua một chiếc 3,6 triệu. Sếp bảo: cùng tiền chi mà marketing hai ngành khác nhau hoàn toàn.',
  concept:{ name:'Tần suất mua × giá trị đơn',
    body:'Tiền khách chi cho một ngành trong năm = <b>tần suất mua</b> × <b>giá trị mỗi lần mua</b>. Hai số này quyết định luật chơi. Mua thường xuyên, giá nhỏ: khách có nhiều dịp thử và đổi hãng (họ hay mua luân phiên vài hãng), nên thắng bằng có mặt khắp nơi và được nhớ đúng lúc. Mua thưa, giá lớn: mỗi lần mua là một cửa sổ ngắn, bạn phải có mặt đúng lúc khách tìm hiểu, và một đánh giá xấu có thể mất cả một khách. Hai số này chưa đủ: mua thường xuyên vẫn có thể trung thành (cà phê quán quen), còn mua thưa vẫn có thể lặp lại theo vòng đời (bảo hiểm, phần mềm gia hạn). Khi đó điều cần đo là <b>tỉ lệ gia hạn hoặc mua lại</b>, không phải số lần có mặt trên kệ.' },
  example:'Dầu gội: 12 lần × 100.000 = 1,2 triệu mỗi năm. Mỗi tháng khách đứng trước kệ một lần, và mỗi lần là một cơ hội để đối thủ chen vào. Hãng dầu gội vì thế đầu tư vào phủ kệ và quảng cáo đều đặn. Nồi chiên: 3,6 triệu ÷ 3 năm = 1,2 triệu mỗi năm, nhưng khách chỉ quyết định một lần. Hãng nồi chiên đầu tư vào đánh giá, video so sánh, chính sách bảo hành, vì cửa sổ mua chỉ mở vài tuần và không có lần thứ hai sớm.',
  takeaway:'Cùng tiền chi mỗi năm, tần suất mua quyết định bạn đánh vào thói quen hay vào lúc cân nhắc.',
  apply:'Chọn hai thứ bạn mua gần đây, một thứ mua hằng tuần và một thứ mua vài năm một lần. Nói trong 60 giây: bạn đã quyết định mỗi thứ khác nhau như thế nào?',
  mistakes:['Chỉ nhìn giá một sản phẩm mà không nhân với tần suất mua.','Dùng cùng một kiểu khuyến mãi cho ngành mua thường xuyên và ngành mua vài năm một lần.'],
  q:[
  { type:'mcq', stem:'Đoán trước: với ngành nồi chiên mua ba năm một lần, điều gì quan trọng nhất để bán được?',
    options:[{k:'a',t:'Phủ thật dày tạp hoá để khách tiện mua mỗi tuần'},{k:'b',t:'Chạy mã giảm giá mỗi tháng để khách quay lại mua thêm một chiếc nữa'},
             {k:'c',t:'Có mặt thuyết phục đúng lúc khách đang tìm hiểu để mua'},{k:'d',t:'Tăng tần suất quảng cáo trên truyền hình quanh năm'}],
    answer:'c', why:{a:'Khách không mua nồi chiên mỗi tuần; phủ tạp hoá không giúp gì.',
      b:'Khách mua xong sẽ không mua thêm nồi thứ hai vì có mã.',
      c:'Đúng. Cửa sổ mua ngắn và hiếm; thắng ở giai đoạn tìm hiểu là thắng cả lần mua.',
      d:'Quảng cáo đều quanh năm tốn tiền cho những người chưa đến lúc mua.'} },
  { type:'mcq', stem:'Bạn phụ trách hãng dầu gội. Ngân sách chỉ đủ cho một hướng. Bạn chọn gì?',
    options:[{k:'a',t:'Làm một video so sánh dài chi tiết cho người đang cân nhắc'},{k:'b',t:'Giữ hàng luôn có mặt và dễ thấy ở các điểm bán chính'},
             {k:'c',t:'Tăng thời hạn bảo hành sản phẩm để tạo niềm tin mua'},{k:'d',t:'Dồn tiền cho một sự kiện ra mắt thật lớn trong năm'}],
    answer:'b', why:{a:'Ít ai xem video dài để chọn dầu gội; quyết định diễn ra vài giây trước kệ.',
      b:'Đúng. Mua 12 lần mỗi năm thì mỗi lần vắng mặt trên kệ là một lần mất khách.',
      c:'Bảo hành không có ý nghĩa với dầu gội.',
      d:'Một sự kiện không đủ cho quyết định lặp lại mỗi tháng.'} },
  { type:'calc', stem:'Khách mua sữa chua 3 lần mỗi tuần, mỗi lần 28.000 đồng. Một năm (52 tuần) khách chi bao nhiêu nghìn đồng cho ngành này?',
    unit:'nghìn đồng', ans:4368, tol:1, wrong:[[1456,'NGUOC_TAN_SUAT'],[84,'SAI_TINH_TOAN']], errors:['NGUOC_TAN_SUAT'],
    steps:['Số lần mua một năm: 3 × 52 = 156 lần.','156 × 28 = <b>4.368 nghìn đồng</b> (khoảng 4,37 triệu).'] },
  { type:'mcq', stem:'Ngành mua thường xuyên, giá nhỏ, khách hay mua luân phiên nhiều hãng. Vì sao?',
    options:[{k:'a',t:'Vì khách mua thường xuyên đa số có thu nhập thấp'},{k:'b',t:'Vì các hãng trong ngành này đều có sản phẩm chất lượng kém'},
             {k:'c',t:'Vì quy định pháp luật không cho hãng giữ chân khách'},{k:'d',t:'Vì mỗi lần mua rủi ro thấp nên khách sẵn lòng thử hãng khác'}],
    answer:'d', why:{a:'Người giàu cũng mua dầu gội mỗi tháng; thu nhập không phải lý do.',
      b:'Chất lượng có thể rất tốt; khách đổi vì rủi ro thử cái mới thấp.',
      c:'Không có quy định như vậy.',
      d:'Đúng. Rủi ro thấp và dịp mua nhiều khiến khách sẵn lòng thử, nên thói quen rất dễ bị chen ngang.'} },
  { type:'mcq', stem:'Tình huống mới: một hãng máy lọc nước bán máy 6 triệu, mỗi 6 tháng khách thay lõi 400.000 đồng. Điều này đổi luật chơi thế nào?',
    options:[{k:'a',t:'Biến ngành mua thưa thành có phần mua lặp lại để giữ khách'},{k:'b',t:'Không đổi gì, vì tiền lõi quá nhỏ so với giá máy'},
             {k:'c',t:'Làm hãng mất khách vì khách ghét phải trả thêm tiền'},{k:'d',t:'Biến máy lọc nước thành ngành mua theo mùa vụ'}],
    answer:'a', why:{a:'Đúng. Lõi lọc tạo quan hệ lặp lại; mỗi lần thay lõi là một lần giữ khách hoặc để lọt khách.',
      b:'800.000 mỗi năm trong nhiều năm là khoản đáng kể và là cơ hội liên lạc thường xuyên.',
      c:'Khách chấp nhận nếu hiểu lợi ích; vấn đề là giữ họ mua lõi chính hãng.',
      d:'Thay lõi theo thời gian dùng, không theo mùa.'} },
  { type:'mcq', stem:'Một phần mềm kế toán cho hộ kinh doanh bán gói 1,2 triệu mỗi năm; khách mua mới hiếm, nhưng ai dùng thì gia hạn hằng năm hoặc bỏ hẳn. Doanh thu mỗi khách theo thời gian, bạn xử lý thế nào?',
    options:[{k:'a',t:'Coi kỳ gia hạn là lần mua thật: nhắc và đo tỉ lệ gia hạn từ 60 ngày trước hạn'},{k:'b',t:'Dồn mã giảm giá cho khách mới, vì khách cũ đã trả tiền rồi'},
             {k:'c',t:'Bán thêm gói thứ hai cho cùng khách ngay trong tháng đầu để tăng doanh thu'},{k:'d',t:'Chờ khách tự quay lại, vì phần mềm dùng tốt thì không cần nhắc nhở'}],
    answer:'a', why:{a:'Đúng. Ngành mua thưa nhưng lặp lại: mỗi kỳ gia hạn là cửa sổ mua mới, và tỉ lệ gia hạn mới là thước đo chính.',
      b:'Dồn tiền cho khách mới trong khi khách cũ rời đi là đổ nước vào thùng thủng.',
      c:'Tháng đầu khách còn chưa biết phần mềm có hợp không; bán thêm sớm dễ phản tác dụng.',
      d:'Khách bận quên gia hạn hoặc bị đối thủ chen vào đúng kỳ; im lặng là để lọt khách.'} },
  { type:'mcq', stem:'Cà phê gói: khách mua 2 lần mỗi tháng, mỗi lần 80.000 đồng. Hãng có hai hướng (số minh hoạ): X nhắc mua lại để khách mua thêm 1 lần mỗi tháng; Y ra gói lớn khiến mỗi lần mua tăng 25% nhưng vẫn 2 lần. Hướng nào cho nhiều doanh thu mỗi khách hơn?',
    options:[{k:'a',t:'Y: 2 × 100.000 = 200.000 đồng mỗi tháng, vì khách bớt phải nghĩ'},{k:'b',t:'X: 3 × 80.000 = 240.000 đồng mỗi tháng, hơn Y 40.000 đồng'},
             {k:'c',t:'Bằng nhau, vì mỗi hướng chỉ đổi một trong hai thừa số'},{k:'d',t:'Y, vì tăng giá trị đơn bền hơn tăng tần suất'}],
    answer:'b', why:{a:'Y tính đúng 200.000 nhưng nhỏ hơn 240.000 của X: tăng 25% giá trị đơn không bằng thêm một lần mua (tăng 50%).',
      b:'Đúng. X cho 240.000 (+50%), Y chỉ 200.000 (+25%). Cần cả biên gộp mới biết lãi, nhưng về doanh thu X hơn.',
      c:'Mỗi hướng đổi một thừa số nhưng mức đổi khác nhau (+50% so với +25%).',
      d:'Bền hơn hay không là giả định chưa có dữ kiện; theo số đã cho, Y thấp hơn X.'} },
  ]},

/* ------------------------------------------------------------------ 04 */
{ id:'B:ob03-04', skill:'insight', read:'6 phút', t:'Khách mua theo thói quen hay mua sau khi cân nhắc?',
  situation:'Bạn nhận hai dự án cùng lúc: một hãng nước mắm và một hãng xe máy điện. Nhóm đề xuất dùng chung một kịch bản: chạy video dài giải thích tính năng, kèm trang so sánh chi tiết với đối thủ. Bạn ra chợ quan sát: bà nội trợ cầm chai nước mắm quen trong 3 giây. Còn ở cửa hàng xe, một cặp vợ chồng đã hỏi 40 phút và hẹn quay lại.',
  concept:{ name:'Mua thói quen và mua cân nhắc',
    body:'Mức <b>dấn thân</b> của khách quyết định cách bạn nói chuyện, và nó đến từ <b>rủi ro cảm nhận</b>: giá, hậu quả nếu chọn sai, mức khách thấy mình hiểu sản phẩm. Ngành <b>mua thói quen</b> (nước mắm, mì gói): rủi ro thấp, khách chọn cái quen, dễ thấy; thắng bằng hiện diện và dấu hiệu nhận diện. Ngành <b>mua cân nhắc</b> (xe, bảo hiểm, khoá học): giá lớn, sợ sai, khách chủ động tìm thông tin; thắng bằng bằng chứng và gỡ từng nỗi lo. Hai cực chỉ là hai đầu của một phổ: kem chống nắng hay bột giặt thương hiệu mới nằm giữa. Ở mọi điểm, nhận biết quyết định bạn có lọt vào danh sách cân nhắc không; bằng chứng chỉ có ích khi khách đã biết bạn. Lưới FCB (Richard Vaughn, 1980) xếp sản phẩm theo mức dấn thân và theo việc khách mua bằng lý trí hay cảm xúc.' },
  example:'Hãng nước mắm: khách quyết định trong 3 giây, nên ngân sách dồn vào màu chai dễ nhận ra, vị trí kệ và nhắc tên đều đặn. Một video 3 phút về quy trình ủ chượp sẽ có ít người xem hết. Hãng xe máy điện: khách mất vài tuần và 40 phút tại cửa hàng; họ lo pin, trạm sạc, giá bán lại. Video dài, bảng so sánh chi phí sạc so với xăng, chính sách đổi pin là đúng chỗ. Chung một kịch bản cho cả hai là phí một nửa ngân sách.',
  takeaway:'Mua thói quen thắng bằng hiện diện và nhận diện; mua cân nhắc thắng bằng bằng chứng gỡ nỗi lo.',
  apply:'Chọn một sản phẩm bạn dùng. Nói trong 60 giây: lần gần nhất bạn mua nó mất bao lâu để quyết, và bạn đã tìm thông tin ở đâu?',
  mistakes:['Viết nội dung dài, nhiều lý lẽ cho sản phẩm khách mua trong vài giây.','Chỉ chạy quảng cáo nhắc tên cho sản phẩm khách cần bằng chứng mới dám mua.'],
  q:[
  { type:'mcq', stem:'Đoán trước: với hãng nước mắm, cách nào giúp bán được nhiều hơn?',
    options:[{k:'a',t:'Video dài 3 phút giải thích quy trình ủ chượp kĩ'},{k:'b',t:'Trang so sánh độ đạm chi tiết với năm hãng khác trên cùng kệ'},
             {k:'c',t:'Hội thảo trực tuyến về cách chọn nước mắm ngon'},{k:'d',t:'Chai dễ nhận ra, có mặt trên kệ và được nhắc đều'}],
    answer:'d', why:{a:'Khách mua trong 3 giây ít khi xem hết video dài.',
      b:'Ít người so độ đạm trước kệ; họ lấy chai quen.',
      c:'Rất ít người dự hội thảo để chọn một chai nước mắm.',
      d:'Đúng. Ngành mua thói quen thắng ở chỗ khách nhận ra và với được.'} },
  { type:'mcq', stem:'Khách xe máy điện hay hỏi "pin hỏng thì sao?". Bạn làm gì với ngân sách nội dung?',
    options:[{k:'a',t:'Tăng tần suất quảng cáo nhắc tên hãng trên mạng xã hội'},{k:'b',t:'Làm nội dung rõ về bảo hành, đổi pin và chi phí thay pin'},
             {k:'c',t:'Thiết kế lại logo cho dễ nhớ và hiện đại hơn đối thủ'},{k:'d',t:'Giảm giá mạnh trong ba ngày để khách quyết định nhanh'}],
    answer:'b', why:{a:'Nhắc tên không gỡ được nỗi lo cụ thể về pin.',
      b:'Đúng. Mua cân nhắc cần gỡ đúng nỗi lo đang chặn quyết định.',
      c:'Logo không trả lời câu hỏi về pin.',
      d:'Giảm giá gấp có thể làm khách nghi ngờ hơn khi họ còn đang lo.'} },
  { type:'mcq', stem:'Dấu hiệu nào cho thấy một ngành là mua cân nhắc?',
    options:[{k:'a',t:'Khách tìm thông tin, hỏi người quen và so sánh trước khi mua'},{k:'b',t:'Sản phẩm được bán ở rất nhiều tạp hoá và siêu thị'},
             {k:'c',t:'Hãng dẫn đầu chạy quảng cáo truyền hình thường xuyên, nhiều lần mỗi ngày'},{k:'d',t:'Sản phẩm có bao bì nhiều màu sắc và dễ nhận ra'}],
    answer:'a', why:{a:'Đúng. Hành vi tìm hiểu chủ động là dấu hiệu rõ nhất của mua cân nhắc.',
      b:'Bán rộng thường là dấu hiệu của ngành mua thói quen.',
      c:'Quảng cáo truyền hình có ở cả hai loại ngành.',
      d:'Bao bì nổi bật quan trọng nhất ở ngành mua thói quen.'} },
  { type:'calc', stem:'Khảo sát (số minh hoạ): 175 trên 250 khách mua điện thoại đọc đánh giá trước khi mua, còn với bột giặt chỉ 25 trên 250 khách. Tỉ lệ đọc đánh giá của điện thoại cao hơn bột giặt bao nhiêu điểm phần trăm?',
    unit:'điểm phần trăm', ans:60, tol:0.1, wrong:[[600,'NHAM_DIEM_PHAN_TRAM'],[80,'SAI_TINH_TOAN']], errors:['NHAM_DIEM_PHAN_TRAM'],
    steps:['Điện thoại: 175 ÷ 250 = 70%. Bột giặt: 25 ÷ 250 = 10%.','Chênh lệch: 70 − 10 = <b>60 điểm phần trăm</b>. (600 là mức tăng tương đối so với 10%, nhầm với điểm phần trăm; 80 là cộng thay vì trừ.)'] },
  { type:'mcq', stem:'Tình huống mới: một hãng bảo hiểm sức khoẻ chạy quảng cáo 6 giây chỉ có logo và câu khẩu hiệu. Doanh số không tăng. Vì sao?',
    options:[{k:'a',t:'Vì quảng cáo 6 giây quá dài với người xem hiện nay'},{k:'b',t:'Vì bảo hiểm là ngành không cần quảng cáo để bán'},
             {k:'c',t:'Vì ngành mua cân nhắc cần bằng chứng, 6 giây không đủ gỡ lo'},{k:'d',t:'Vì logo của hãng chưa đủ đẹp để khách nhớ'}],
    answer:'c', why:{a:'6 giây là ngắn; vấn đề là thiếu nội dung, không phải quá dài.',
      b:'Bảo hiểm vẫn cần tiếp thị, nhưng theo kiểu khác.',
      c:'Đúng. Khách cần hiểu quyền lợi, loại trừ, cách bồi thường trước khi ký.',
      d:'Nhận diện tốt vẫn không trả lời được câu hỏi của khách.'} },
  { type:'mcq', stem:'Cùng là cà phê, nhưng máy pha cà phê tại nhà khác gói cà phê hoà tan ở điểm nào về cách mua?',
    options:[{k:'a',t:'Không khác, vì cùng ngành cà phê nên cùng cách mua'},{k:'b',t:'Máy pha là mua cân nhắc, gói hoà tan là mua thói quen'},
             {k:'c',t:'Gói hoà tan là mua cân nhắc vì khách phải so rất nhiều vị và nhiều hãng'},{k:'d',t:'Cả hai đều mua cân nhắc vì liên quan sức khoẻ'}],
    answer:'b', why:{a:'Cùng chủ đề cà phê nhưng mức dấn thân khác hẳn.',
      b:'Đúng. Giá, rủi ro và tần suất khác nhau khiến cách mua khác nhau.',
      c:'Khách thường lấy vị quen; ít ai so kĩ mỗi lần.',
      d:'Gói hoà tan giá nhỏ, mua lặp lại, không có nhiều cân nhắc.'} },
  { type:'mcq', stem:'Một kem chống nắng thương hiệu mới (250.000 đồng, mua vài lần mỗi năm, khách lo hợp da hay không) nằm giữa hai cực. Ngân sách hạn chế, bạn ưu tiên gì?',
    options:[{k:'a',t:'Chỉ nhắc tên và dồn kệ, vì kem chống nắng là hàng mua nhanh'},{k:'b',t:'Dùng thử và đánh giá thật gỡ lo hợp da, cùng hiện diện nơi khách tìm'},
             {k:'c',t:'Video dài 5 phút về công nghệ lọc tia UV, vì khách đã chịu tìm hiểu'},{k:'d',t:'Giảm 50% cả tháng đầu, vì giá là rào cản duy nhất của khách'}],
    answer:'b', why:{a:'Nhắc tên giúp nhận biết nhưng không gỡ nỗi lo hợp da, và 250.000 đồng đủ để khách thấy rủi ro.',
      b:'Đúng. Sản phẩm giữa hai cực cần cả hai: lọt vào danh sách cân nhắc nhờ hiện diện, rồi bằng chứng nhẹ (dùng thử, đánh giá thật) để gỡ lo.',
      c:'Mức dấn thân ở giữa: khách không bỏ 5 phút xem công nghệ, họ cần bằng chứng nhanh về da của mình.',
      d:'Giá không phải nỗi lo chính, và giảm sâu thương hiệu mới còn gây nghi ngờ chất lượng.'} },
  ]},

/* ------------------------------------------------------------------ 05 */
{ id:'B:ob03-05', skill:'brand', read:'7 phút', t:'Ai dẫn đầu ngành, và họ dẫn đầu nhờ đâu?',
  situation:'Bạn chuẩn bị ra mắt một hãng sữa tươi mới. Cả nhóm nói: "Vinamilk dẫn đầu vì quảng cáo nhiều". Bạn thấy lời giải thích đó quá dễ. Bạn đi 20 tạp hoá ở một quận: 19 nơi có Vinamilk, 12 nơi có TH true MILK, 5 nơi có hãng khác. Ở siêu thị, hai hãng này chiếm phần lớn tủ mát.',
  concept:{ name:'Nguồn gốc vị trí dẫn đầu',
    body:'Mỗi ngành có một hai hãng dẫn đầu, và lý do họ dẫn đầu chính là <b>luật chơi</b> của ngành. Có bốn nguồn hay gặp: <b>độ phủ phân phối</b>, <b>thói quen và trí nhớ</b> tích luỹ nhiều năm, <b>lợi thế chi phí</b> nhờ quy mô, và <b>kiểm soát nguồn cung</b> (trang trại, nhà máy, công thức). Ở ngành khác còn có bản quyền hoặc hiệu ứng mạng (càng nhiều người dùng càng khó bỏ). Các nguồn không ngang nhau: với hàng mua nhanh, phân phối gần như là điều kiện cần (không có mặt thì không có doanh số), còn thói quen và chi phí quyết định giữ được vị trí hay không. Đọc sai nguồn thì đánh sai chỗ: khách thích bạn nhưng ra tiệm không thấy bạn. Câu hỏi đúng: nguồn nào của họ yếu đi nếu bạn vào được một kênh họ chưa mạnh?' },
  example:'Đo độ phủ: Vinamilk có mặt 19/20 tạp hoá = 95%; TH 12/20 = 60%; hãng khác 5/20 = 25%. Với sữa tươi, khách mua theo thói quen, gần nhà; không có mặt thì không có doanh số. Vậy nguồn dẫn đầu chính ở đây là độ phủ và thói quen, cùng với nguồn sữa và nhà máy quy mô lớn. Hãng mới không thể phủ 95% ngay. Hướng thực tế: chọn một khu vực hẹp, phủ dày tạp hoá ở đó trước. Hoặc vào một kênh mà độ phủ tạp hoá không còn là lợi thế riêng, như cửa hàng tiện lợi hay giao tận nhà, và đo xem nguồn nào của hãng lớn yếu đi ở đó.',
  takeaway:'Tìm ra người dẫn đầu thắng nhờ gì, rồi chọn chỗ họ khó phản ứng thay vì đánh trực diện.',
  apply:'Chọn một ngành bạn biết. Nói trong 60 giây: hãng dẫn đầu thắng nhờ nguồn nào trong bốn nguồn, và bằng chứng quan sát được là gì?',
  mistakes:['Giải thích mọi vị trí dẫn đầu bằng "quảng cáo nhiều".','Đánh trực diện vào đúng thế mạnh của người dẫn đầu.'],
  q:[
  { type:'mcq', stem:'Đoán trước: ở ngành sữa tươi, nguồn dẫn đầu nào khó sao chép nhất với một hãng mới?',
    options:[{k:'a',t:'Một câu khẩu hiệu quảng cáo dễ nhớ và vui tai'},{k:'b',t:'Độ phủ gần như các tạp hoá cộng nguồn sữa lớn'},
             {k:'c',t:'Bao bì màu sắc tươi sáng và dễ nhận diện'},{k:'d',t:'Đợt khuyến mãi mua hai tặng một mỗi cuối tuần'}],
    answer:'b', why:{a:'Khẩu hiệu có thể viết trong một tuần.',
      b:'Đúng. Mạng lưới phân phối và nguồn nguyên liệu mất nhiều năm và nhiều vốn để xây.',
      c:'Bao bì có thể thiết kế lại nhanh.',
      d:'Khuyến mãi ai cũng làm được ngay.'} },
  { type:'mcq', stem:'Hãng mới chỉ đủ vốn phủ 400 tạp hoá. Bạn chọn cách nào?',
    options:[{k:'a',t:'Rải 400 điểm đều khắp cả nước để có mặt nhiều tỉnh'},{k:'b',t:'Bỏ tạp hoá, dồn tiền vào quảng cáo trên mạng'},
             {k:'c',t:'Dồn 400 điểm vào vài quận để phủ dày ở một khu'},{k:'d',t:'Chỉ bán ở siêu thị lớn để hình ảnh cao cấp hơn'}],
    answer:'c', why:{a:'Rải mỏng thì ở đâu cũng hiếm thấy, khách không hình thành thói quen.',
      b:'Quảng cáo tạo nhu cầu nhưng khách không tìm thấy hàng gần nhà.',
      c:'Đúng. Phủ dày một khu tạo độ phủ cao tại chỗ, đủ để thói quen hình thành rồi mở rộng dần.',
      d:'Sữa tươi mua theo thói quen gần nhà; chỉ siêu thị lớn là bỏ đi phần lớn dịp mua.'} },
  { type:'calc', stem:'Bạn khảo sát 40 tạp hoá, hãng A có mặt ở 34 tạp hoá. Độ phủ của hãng A là bao nhiêu phần trăm?',
    unit:'%', ans:85, tol:0.1, wrong:[[117.6,'SAI_MAU_SO'],[15,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO'],
    steps:['Độ phủ = số điểm có hàng ÷ số điểm khảo sát.','34 ÷ 40 = 0,85 = <b>85%</b>.'] },
  { type:'mcq', stem:'Vì sao nói "người dẫn đầu thắng nhờ quảng cáo nhiều" thường là giải thích chưa đủ?',
    options:[{k:'a',t:'Vì hãng dẫn đầu thực ra gần như không chạy quảng cáo'},{k:'b',t:'Vì quảng cáo chỉ kéo khách thử, không giữ được khách quay lại'},
             {k:'c',t:'Vì ngân sách quảng cáo của họ nhỏ hơn đối thủ nhỏ'},{k:'d',t:'Vì quảng cáo vừa góp phần tạo thị phần, vừa là kết quả của thị phần lớn'}],
    answer:'d', why:{a:'Hãng dẫn đầu thường có quảng cáo; vấn đề là chiều nhân quả, không phải có hay không.',
      b:'Quảng cáo vẫn giúp khách nhớ hãng; điểm chính là nó không đứng một mình giải thích được vị trí dẫn đầu.',
      c:'Thường ngược lại: hãng lớn có ngân sách lớn hơn.',
      d:'Đúng. Quan hệ hai chiều: thị phần lớn mới có tiền chi nhiều, nên phải xem thêm phân phối, thói quen, chi phí.'} },
  { type:'mcq', stem:'Tình huống mới: một hãng cà phê chuỗi dẫn đầu nhờ có cửa hàng ở hầu hết góc phố đông người. Hãng mới nên đánh vào đâu?',
    options:[{k:'a',t:'Mở cửa hàng ngay cạnh mỗi cửa hàng của hãng dẫn đầu'},{k:'b',t:'Một dịp mua mà vị trí góc phố không giúp gì, như giao tận văn phòng'},
             {k:'c',t:'Giảm giá một nửa trong ba tháng để kéo khách quen của hãng dẫn đầu'},{k:'d',t:'Làm logo và màu sắc cửa hàng giống hãng dẫn đầu'}],
    answer:'b', why:{a:'Đối đầu trực tiếp vào đúng thế mạnh, lại tốn tiền thuê mặt bằng đắt.',
      b:'Đúng. Chọn dịp mua mà lợi thế vị trí không phát huy, hãng lớn khó phản ứng nhanh.',
      c:'Hãng lớn có thể giảm giá theo và chịu lâu hơn.',
      d:'Bắt chước làm khách nhớ đến hãng lớn chứ không nhớ bạn.'} },
  { type:'mcq', stem:'Hãng X có mặt ở 90% tạp hoá nhưng chỉ chiếm 20% kệ ở chuỗi cửa hàng tiện lợi, nơi khách trẻ mua nhiều. Dữ kiện này gợi ý gì về nguồn dẫn đầu của X?',
    options:[{k:'a',t:'X mạnh nhờ độ phủ tạp hoá, nên yếu hơn ở kênh khách trẻ'},{k:'b',t:'X có lợi thế chi phí vượt trội, vì ở đâu cũng bán được giá thấp nhất'},
             {k:'c',t:'X kiểm soát nguồn cung, nên ở kênh nào cũng khó bị thay thế'},{k:'d',t:'X được khách nhớ rất sâu, nên ít chỗ trên kệ cũng không sao'}],
    answer:'a', why:{a:'Đúng. Nguồn mạnh theo kênh: lợi thế bám vào mạng lưới tạp hoá và mất đi khi kênh khác không cần mạng lưới đó.',
      b:'Lợi thế chi phí sẽ thể hiện ở mọi kênh; dữ kiện cho thấy sức mạnh phụ thuộc kênh.',
      c:'Kiểm soát nguồn cung sẽ giúp X giữ chỗ ở mọi kênh, nhưng X chỉ chiếm 20% kệ tiện lợi.',
      d:'Nếu trí nhớ đủ mạnh, kệ ít chỗ vẫn bán được; thực tế X vắng ở kênh này, nên không phải nguồn chính.'} },
  { type:'mcq', stem:'Một hãng dẫn đầu nhờ giá thấp do sản xuất quy mô lớn. Chiến lược nào của người mới dễ thất bại nhất?',
    options:[{k:'a',t:'Chọn nhóm khách chịu trả thêm cho một đặc điểm riêng'},{k:'b',t:'Bán ở một kênh mà hãng dẫn đầu chưa chú trọng'},
             {k:'c',t:'Cạnh tranh bằng giá thấp hơn cả hãng dẫn đầu'},{k:'d',t:'Tập trung phục vụ tốt một khu vực địa lý nhỏ trước'}],
    answer:'c', why:{a:'Tránh được cuộc chơi giá, nhưng chỉ thành công nếu nhóm khách đó đủ lớn để trả chi phí phục vụ riêng.',
      b:'Đánh chỗ đối thủ yếu, nhưng chỉ thành công nếu kênh đủ doanh số và hãng lớn chưa kịp vào theo.',
      c:'Đúng, đây là cách dễ thất bại: hãng dẫn đầu có chi phí thấp hơn nên chịu được giá thấp lâu hơn.',
      d:'Tập trung nguồn lực hợp lý, nhưng chỉ thành công nếu khu vực nhỏ đủ để thành thói quen và có đường mở rộng.'} },
  ]},

/* ------------------------------------------------------------------ 06 */
{ id:'B:ob03-06', skill:'measure', read:'7 phút', t:'Ngành này để lại bao nhiêu lãi trên mỗi đồng bán ra?',
  situation:'Bạn được mời làm marketing cho hai công ty: một hãng mỹ phẩm chăm sóc da và một nhà phân phối gạo. Cả hai đều có doanh thu 100 tỉ đồng một năm. Hãng mỹ phẩm chi 25 tỉ cho quảng cáo và vẫn có lãi. Nhà phân phối gạo nói ngân sách marketing chỉ khoảng 1 tỉ, và họ không hiểu vì sao hãng kia dám chi nhiều thế.',
  concept:{ name:'Biên lợi nhuận gộp điển hình của ngành',
    body:'<b>Biên lợi nhuận gộp</b> = (giá bán − giá vốn) ÷ giá bán. Mỗi ngành có một mức biên gộp điển hình, và nó đặt trần cho số tiền bạn có để làm marketing. Mỹ phẩm, đồ uống có thương hiệu thường có biên gộp cao, vì phần lớn giá trị nằm ở thương hiệu chứ không ở nguyên liệu. Gạo, xăng, điện tử phổ thông có biên gộp thấp, vì khách so giá và sản phẩm khó khác biệt. Marketing lấy từ phần còn lại sau chi phí vận hành, nên biên gộp là điều kiện cần chứ chưa đủ: ngân sách tối đa = lãi gộp − chi phí vận hành − lãi mong muốn. Ngành biên thấp thắng bằng khối lượng và chi phí vận hành; ngành biên cao thắng bằng thương hiệu và nội dung.' },
  example:'Hãng mỹ phẩm: bán 100 tỉ, giá vốn 30 tỉ, lãi gộp 70 tỉ, biên gộp 70%. Chi 25 tỉ quảng cáo và 25 tỉ vận hành, vẫn còn 20 tỉ. Nhà phân phối gạo: bán 100 tỉ, giá vốn 88 tỉ, lãi gộp 12 tỉ, biên gộp 12%. Nếu học theo mỹ phẩm chi 25 tỉ quảng cáo, họ lỗ ngay 13 tỉ trước cả khi trả lương. Nếu chi vận hành 9 tỉ và muốn giữ lãi 1 tỉ, trần marketing chỉ là 12 − 9 − 1 = 2 tỉ. Luật chơi của ngành gạo là tối ưu kho vận và hợp đồng với đại lý, không phải thắng bằng quảng cáo.',
  takeaway:'Biên gộp của ngành quyết định bạn có bao nhiêu đạn để làm marketing.',
  apply:'Chọn một sản phẩm quen thuộc. Đoán xem trong giá bán, bao nhiêu phần là nguyên liệu. Nói trong 60 giây: ngành này biên cao hay thấp, và vì sao?',
  mistakes:['Sao chép mức ngân sách quảng cáo của ngành biên cao sang ngành biên thấp.','Nhầm doanh thu với lãi khi đánh giá một ngành có đáng làm hay không.'],
  q:[
  { type:'mcq', stem:'Đoán trước: ngành nào thường có biên lợi nhuận gộp cao hơn?',
    options:[{k:'a',t:'Gạo đóng bao bán cho các đại lý'},{k:'b',t:'Xăng dầu bán lẻ tại cây xăng'},
             {k:'c',t:'Điện thoại phổ thông bán ở các chuỗi lớn'},{k:'d',t:'Kem dưỡng da có thương hiệu riêng'}],
    answer:'d', why:{a:'Gạo khó khác biệt, khách so giá; biên thấp.',
      b:'Giá xăng được điều tiết; biên bán lẻ thấp.',
      c:'Điện thoại phổ thông cạnh tranh giá gay gắt; biên thấp.',
      d:'Đúng. Phần lớn giá trị nằm ở thương hiệu và công thức, không ở nguyên liệu.'} },
  { type:'mcq', stem:'Nhà phân phối gạo muốn tăng trưởng. Bạn đề xuất ưu tiên gì?',
    options:[{k:'a',t:'Chi 20 tỉ quảng cáo truyền hình để xây thương hiệu'},{k:'b',t:'Thuê người nổi tiếng làm gương mặt đại diện cả năm'},
             {k:'c',t:'Mở rộng đại lý và giảm chi phí vận chuyển mỗi tấn'},{k:'d',t:'Tăng giá bán 30% để có biên gộp như ngành mỹ phẩm'}],
    answer:'c', why:{a:'Với lãi gộp 12 tỉ, chi 20 tỉ quảng cáo là lỗ chắc.',
      b:'Chi phí lớn, không phù hợp ngành biên thấp.',
      c:'Đúng. Ngành biên thấp thắng bằng khối lượng và chi phí vận hành.',
      d:'Khách so giá gạo; tăng 30% sẽ mất khách hàng loạt.'} },
  { type:'calc', stem:'Một hộp kem dưỡng bán 400.000 đồng, giá vốn 120.000 đồng. Biên lợi nhuận gộp là bao nhiêu phần trăm?',
    unit:'%', ans:70, tol:0.1, wrong:[[30,'NHAM_GIA_VON'],[233.3,'SAI_MAU_SO']], errors:['NHAM_GIA_VON','SAI_MAU_SO'],
    steps:['Lãi gộp = 400.000 − 120.000 = 280.000 đồng.','Biên gộp = 280.000 ÷ 400.000 = <b>70%</b>.'] },
  { type:'mcq', stem:'Vì sao ngành mỹ phẩm có thể chi 25% doanh thu cho quảng cáo mà vẫn có lãi?',
    options:[{k:'a',t:'Vì mỹ phẩm được miễn thuế nên còn nhiều tiền hơn'},{k:'b',t:'Vì biên gộp cao nên sau giá vốn vẫn còn đủ tiền'},
             {k:'c',t:'Vì quảng cáo mỹ phẩm rẻ hơn quảng cáo các ngành khác'},{k:'d',t:'Vì khách mỹ phẩm mua thường xuyên hơn các ngành khác'}],
    answer:'b', why:{a:'Không có miễn thuế như vậy.',
      b:'Đúng. Biên gộp 70% nghĩa là mỗi 100 đồng còn 70 đồng để chi cho quảng cáo, vận hành và lãi.',
      c:'Giá quảng cáo không phụ thuộc ngành theo cách đó.',
      d:'Số lượng mua không phải lý do; lý do là tiền còn lại sau giá vốn.'} },
  { type:'mcq', stem:'Tình huống mới: chuỗi trà sữa bán ly 45.000 đồng, nguyên liệu 13.500 đồng. Nhưng chủ chuỗi vẫn than lãi mỏng. Giải thích hợp lý nhất?',
    options:[{k:'a',t:'Mặt bằng, nhân công, phí app giao đồ ăn ăn phần lớn lãi gộp'},{k:'b',t:'Biên gộp chỉ khoảng 30%, quá thấp so với mức chung của ngành đồ uống'},
             {k:'c',t:'Nguyên liệu tính sai, thực tế phải đắt gấp ba lần'},{k:'d',t:'Chủ chuỗi nói quá để giảm tiền thuê mặt bằng'}],
    answer:'a', why:{a:'Đúng. Biên gộp 70% nhưng chi phí cố định và phí kênh lớn khiến lãi ròng mỏng.',
      b:'Biên gộp là (45.000 − 13.500) ÷ 45.000 = 70%, không phải 30%.',
      c:'Không có dữ kiện cho thấy nguyên liệu tính sai.',
      d:'Suy đoán động cơ không có căn cứ.'} },
  { type:'mcq', stem:'Bạn chuyển từ ngành mỹ phẩm sang ngành điện máy. Thói quen nào cần sửa?',
    options:[{k:'a',t:'Đọc kĩ phản hồi của khách trên các sàn thương mại điện tử mỗi tuần'},{k:'b',t:'Theo dõi doanh số theo từng kênh bán hàng'},
             {k:'c',t:'Kiểm tra đối thủ đang khuyến mãi những gì'},{k:'d',t:'Đề xuất ngân sách quảng cáo theo tỉ lệ doanh thu cũ'}],
    answer:'d', why:{a:'Thói quen tốt ở mọi ngành.',
      b:'Thói quen tốt ở mọi ngành.',
      c:'Thói quen tốt ở mọi ngành.',
      d:'Đúng. Điện máy biên thấp hơn nhiều; tỉ lệ ngân sách của mỹ phẩm sẽ làm lỗ.'} },
  { type:'mcq', stem:'Nhà phân phối gạo có lãi gộp 12 tỉ, chi phí vận hành 9 tỉ, muốn giữ lãi 1 tỉ. Giám đốc xin 3 tỉ cho xây thương hiệu. Bạn làm gì?',
    options:[{k:'a',t:'Duyệt đủ 3 tỉ, vì thương hiệu mạnh sẽ tự nâng biên gộp về sau'},{k:'b',t:'Từ chối mọi chi phí marketing, vì ngành biên thấp không cần thương hiệu'},
             {k:'c',t:'Chỉ trần 2 tỉ theo phép tính, xin thêm khi chứng minh được tăng lãi gộp'},{k:'d',t:'Duyệt 3 tỉ và hạ lãi mong muốn xuống âm 1 tỉ cho đủ tiền'}],
    answer:'c', why:{a:'Niềm tin biên gộp sẽ tự tăng chưa có bằng chứng; chi 3 tỉ khi trần là 2 tỉ là lỗ ngay.',
      b:'Ngành biên thấp vẫn cần marketing, chỉ là ngân sách nhỏ và nhắm vào việc làm tăng khối lượng hoặc lãi gộp.',
      c:'Đúng. Trần là 12 − 9 − 1 = 2 tỉ; muốn chi thêm phải chứng minh phần chi thêm làm lãi gộp tăng đủ bù.',
      d:'Chấp nhận lỗ để đủ tiền là bỏ qua ràng buộc, không phải giải pháp.'} },
  ]},

/* ------------------------------------------------------------------ 07 */
{ id:'B:ob03-07', skill:'channel', read:'6 phút', t:'Ngành của bạn bán mạnh vào tháng nào?',
  situation:'Bạn phụ trách một hãng bánh kẹo. Ngân sách quảng cáo năm là 12 tỉ, nhóm đề xuất chia đều 1 tỉ mỗi tháng cho "ổn định". Bạn xem số liệu năm ngoái: tháng trước Tết âm lịch chiếm 35% doanh số cả năm, dịp Trung thu chiếm thêm 15%, mười tháng còn lại chia nhau 50%.',
  concept:{ name:'Mùa vụ của ngành',
    body:'Nhiều ngành có <b>mùa vụ</b>: nhu cầu dồn vào vài thời điểm trong năm. Bánh kẹo dồn vào Tết và Trung thu, điều hoà vào mùa nóng, đồ dùng học tập vào tháng 8. Mùa vụ đổi luật chơi: quyết định mua dồn vào vài tuần, kệ hàng và ngân sách đối thủ cũng dồn vào đúng lúc đó. Chia đều ngân sách là tiêu tiền vào tháng khách không mua và thiếu tiền đúng lúc họ mua. Nguyên tắc: lấy tỉ trọng doanh số từng thời kỳ làm <b>điểm xuất phát</b>, rồi chỉnh theo hiệu suất và giá thầu: đỉnh đắt hơn nên đồng cận biên có thể kém hơn, và bắt đầu sớm vài tuần vì khách lên kế hoạch trước. Đừng tắt hẳn quanh năm: giữ hiện diện tối thiểu. Đo mùa vụ bằng <b>chỉ số mùa vụ</b> = doanh số tháng ÷ trung bình tháng, tính từ ít nhất ba năm; khuyến mãi trái mùa làm méo chỉ số nên cần loại ra.' },
  example:'Theo tỉ trọng: dịp Tết nhận 35% × 12 tỉ = 4,2 tỉ; Trung thu 15% × 12 = 1,8 tỉ; mười tháng còn lại 6 tỉ, khoảng 0,6 tỉ mỗi tháng. Trong 4,2 tỉ của Tết, nên bắt đầu từ 5–6 tuần trước Tết, vì các gia đình và doanh nghiệp đặt giỏ quà sớm. Chỉ số mùa vụ của tháng Tết: 35% so với trung bình 1/12 ≈ 8,3% là khoảng 4,2 lần. Chia đều 1 tỉ mỗi tháng thì Tết chỉ có khoảng 1–1,5 tỉ, trong khi đối thủ dồn tiền vào đúng lúc đó.',
  takeaway:'Tiền đi theo lúc khách mua: phân bổ theo mùa vụ và bắt đầu trước đỉnh.',
  apply:'Chọn một ngành. Nói trong 60 giây: ba tháng nào khách mua nhiều nhất, và bạn sẽ bắt đầu quảng cáo từ lúc nào?',
  mistakes:['Chia đều ngân sách cho mọi tháng vì "cho ổn định".','Bắt đầu quảng cáo đúng ngày cao điểm, khi khách đã quyết xong.'],
  q:[
  { type:'mcq', stem:'Đoán trước: với ngành bánh kẹo, chia đều 1 tỉ mỗi tháng gây hậu quả gì?',
    options:[{k:'a',t:'Không sao, vì khách nhớ thương hiệu quanh năm'},{k:'b',t:'Tiết kiệm được tiền vì không phải đua với đối thủ'},
             {k:'c',t:'Thiếu tiền lúc Tết và thừa tiền lúc khách ít mua'},{k:'d',t:'Tăng doanh số đều cho cả mười hai tháng trong năm'}],
    answer:'c', why:{a:'Nhớ quanh năm vẫn không bù được việc vắng mặt đúng lúc mua.',
      b:'Không đua đúng lúc thì mất phần doanh số lớn nhất.',
      c:'Đúng. Tiền nằm sai chỗ so với lúc khách mua.',
      d:'Quảng cáo không tạo ra nhu cầu mua bánh Tết vào tháng 5.'} },
  { type:'mcq', stem:'Bạn có 4,2 tỉ cho dịp Tết. Bạn chọn thời điểm nào để bắt đầu?',
    options:[{k:'a',t:'Khoảng 5–6 tuần trước Tết, khi khách bắt đầu đặt quà'},{k:'b',t:'Đúng tuần cuối trước Tết, lúc chợ đông người nhất'},
             {k:'c',t:'Sau Tết, khi đối thủ đã ngừng chạy quảng cáo'},{k:'d',t:'Rải đều từ tháng 7 để khách nhớ thương hiệu thật lâu trước khi Tết đến'}],
    answer:'a', why:{a:'Đúng. Giỏ quà doanh nghiệp và gia đình được đặt sớm; phải có mặt lúc họ lên kế hoạch.',
      b:'Tuần cuối nhiều người đã mua xong; bạn chỉ còn phần nhỏ.',
      c:'Sau Tết nhu cầu bánh kẹo rơi mạnh.',
      d:'Rải từ tháng 7 làm loãng tiền vào lúc chưa ai mua.'} },
  { type:'calc', stem:'Ngân sách năm 12 tỉ. Dịp Trung thu chiếm 15% doanh số cả năm. Nếu phân bổ theo tỉ trọng doanh số, Trung thu nhận bao nhiêu tỉ đồng?',
    unit:'tỉ đồng', ans:1.8, tol:0.01, wrong:[[1,'SAI_MAU_SO'],[0.8,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO'],
    steps:['Phân bổ theo tỉ trọng: 12 × 15%.','12 × 0,15 = <b>1,8 tỉ</b>. (1 tỉ là chia đều theo tháng, không theo tỉ trọng.)'] },
  { type:'mcq', stem:'Vì sao trong mùa cao điểm chi phí quảng cáo thường đắt hơn?',
    options:[{k:'a',t:'Vì Nhà nước tăng thuế quảng cáo vào dịp lễ Tết'},{k:'b',t:'Vì người xem ít online hơn trong dịp lễ Tết'},
             {k:'c',t:'Vì các nền tảng tính phí cố định cao hơn cuối năm'},{k:'d',t:'Vì nhiều hãng cùng đấu giá cho cùng lượng người xem'}],
    answer:'d', why:{a:'Không có thuế như vậy.',
      b:'Lượng người xem không giảm; nhu cầu mua quảng cáo tăng.',
      c:'Giá thường do đấu giá, không phải phí cố định.',
      d:'Đúng. Cầu quảng cáo tăng đột biến đẩy giá mỗi lượt hiển thị lên.'} },
  { type:'mcq', stem:'Tình huống mới: một hãng máy lạnh nhỏ thấy các hãng lớn dồn tiền vào tháng 4–6. Hướng nào khôn ngoan?',
    options:[{k:'a',t:'Dồn ngân sách vào tháng 5 để vượt tiếng nói của các hãng lớn'},{k:'b',t:'Ưu đãi lắp đặt sớm từ tháng 2–3, trước khi giá quảng cáo lên'},
             {k:'c',t:'Chỉ quảng cáo vào tháng 12 khi không ai chạy'},{k:'d',t:'Bỏ quảng cáo, chờ khách tự tìm đến cửa hàng'}],
    answer:'b', why:{a:'Đọ tiền trực diện lúc đắt nhất là bất lợi cho hãng nhỏ.',
      b:'Đúng. Đón khách lên kế hoạch sớm, chi phí rẻ hơn, thợ lắp đặt còn rảnh.',
      c:'Tháng 12 gần như không ai mua máy lạnh.',
      d:'Hãng nhỏ không được ưu tiên khi khách tự tìm.'} },
  { type:'mcq', stem:'Làm sao biết ngành của bạn có mùa vụ hay không?',
    options:[{k:'a',t:'Xem doanh số theo tháng của vài năm liền'},{k:'b',t:'Hỏi ý kiến nhân viên bán hàng mới vào làm'},
             {k:'c',t:'Xem đối thủ có chạy quảng cáo hôm nay'},{k:'d',t:'Đếm số lượt thích trên trang của hãng'}],
    answer:'a', why:{a:'Đúng. Mẫu lặp lại qua nhiều năm mới là mùa vụ, không phải biến động ngẫu nhiên.',
      b:'Người mới chưa có đủ trải nghiệm qua các mùa.',
      c:'Một thời điểm không cho biết quy luật cả năm.',
      d:'Lượt thích không phản ánh doanh số theo mùa.'} },
  { type:'mcq', stem:'Giá thầu quảng cáo tháng Tết cao hơn khoảng 40% so với tháng thường (số minh hoạ), trong khi tỉ trọng doanh số Tết là 35%. Bạn làm gì với quy tắc phân bổ theo tỉ trọng?',
    options:[{k:'a',t:'Giữ đúng 35% cho dịp Tết, vì tỉ trọng doanh số là quy tắc cuối cùng, không chỉnh'},{k:'b',t:'Lấy tỉ trọng làm điểm xuất phát, dịch bớt tiền sang các tuần trước đỉnh khi giá còn rẻ'},
             {k:'c',t:'Bỏ hẳn quảng cáo dịp Tết, vì giá đắt hơn thì mỗi đồng đều không đáng chi'},{k:'d',t:'Chia lại đều 1 tỉ mỗi tháng để khỏi phải đấu giá lúc giá đang đắt nhất'}],
    answer:'b', why:{a:'Tỉ trọng chỉ là heuristic; giá thầu đắt hơn làm đồng cận biên ở đỉnh kém hơn, nên cần chỉnh.',
      b:'Đúng. Tỉ trọng là điểm xuất phát, rồi chỉnh theo giá: dịch tiền sang giai đoạn khách đã bắt đầu lên kế hoạch mà giá chưa lên.',
      c:'Giá đắt hơn 40% chưa có nghĩa không còn lãi; doanh số Tết vẫn lớn gấp nhiều lần tháng thường.',
      d:'Chia đều đưa tiền ra khỏi tháng khách mua và giảm hiện diện đúng lúc, tệ hơn việc trả giá đắt.'} },
  ]},

/* ------------------------------------------------------------------ 08 */
{ id:'B:ob03-08', skill:'channel', read:'7 phút', t:'Khách của ngành này mua ở đâu nhiều nhất?',
  situation:'Bạn ra mắt một thương hiệu dầu ăn. Nhóm muốn tập trung bán trên sàn thương mại điện tử vì "xu hướng là online". Giả sử bạn xem số liệu ngành (số minh hoạ cho bài, không phải thống kê chính thức): khoảng 60% dầu ăn được mua ở chợ và tạp hoá, 30% ở siêu thị và cửa hàng tiện lợi, chỉ 10% trên sàn. Trong khi đó, ngành mỹ phẩm chăm sóc da bán online khoảng 45%.',
  concept:{ name:'Kênh chính của ngành',
    body:'Mỗi ngành có một <b>kênh chính</b>, nơi phần lớn khách mua. Kênh chính do bản chất sản phẩm và hạ tầng giao hàng quyết định: hàng nặng, mua thường xuyên, cần ngay (dầu ăn, nước mắm, gạo) đi theo kênh gần nhà; hàng nhẹ, giá trị cao, nhiều lựa chọn, cần xem đánh giá (mỹ phẩm, phụ kiện điện thoại) hợp với online. Giao nhanh hay livestream có thể dịch kênh. Chưa có báo cáo ngành thì tự ước lượng: đến 5 điểm bán, đếm số mặt kệ (facing) và hỏi chủ tiệm nhập từ đâu. Đừng quên kênh B2B (nhà hàng, bếp ăn) có thể là kênh lớn của dầu ăn. Chọn kênh ngược luật ngành nghĩa là bạn bơi ở hồ nhỏ.' },
  example:'Giả sử ngành dầu ăn 10.000 tỉ đồng. Kênh chợ và tạp hoá chiếm 60% = 6.000 tỉ, siêu thị và tiện lợi 3.000 tỉ, sàn online 1.000 tỉ. Nếu chỉ bán online và giành 10% kênh này, bạn có 100 tỉ. Nếu giành 2% kênh tạp hoá, bạn có 120 tỉ, nhưng cần đội bán hàng và nhà phân phối. Giả định thêm trong ví dụ này: khách mua dầu ăn online chủ yếu mua kèm trong đơn lớn nên khó thành kênh chính. Quyết định đúng: xây kênh tạp hoá từng vùng, online chỉ là kênh phụ.',
  takeaway:'Bán ở nơi khách của ngành đang mua, không phải nơi đang có tin tức.',
  apply:'Chọn một ngành. Nói trong 60 giây: kênh nào chiếm phần lớn doanh số, và vì sao bản chất sản phẩm đưa khách đến kênh đó?',
  mistakes:['Chọn kênh theo xu hướng chung mà không xem tỉ trọng kênh của ngành.','Nghĩ online luôn rẻ hơn mà quên phí sàn, vận chuyển và đổi trả.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao dầu ăn ít được mua online?',
    options:[{k:'a',t:'Vì phần lớn người mua dầu ăn không dùng điện thoại để mua sắm'},{k:'b',t:'Vì sàn thương mại điện tử cấm bán thực phẩm dạng lỏng'},
             {k:'c',t:'Vì hàng nặng, giá thấp, cần ngay nên phí giao lớn so với giá trị'},{k:'d',t:'Vì giá dầu ăn trên sàn luôn cao hơn ngoài chợ rất nhiều'}],
    answer:'c', why:{a:'Hầu hết người nội trợ đều dùng điện thoại; vấn đề không nằm ở đó.',
      b:'Sàn vẫn cho bán dầu ăn.',
      c:'Đúng. Phí giao cao so với giá trị, và khách thường cần dùng ngay, nên tạp hoá gần nhà tiện hơn.',
      d:'Không có dữ kiện; và chênh giá không phải lý do chính.'} },
  { type:'mcq', stem:'Nhóm vẫn muốn bán online dầu ăn. Bạn đề xuất gì?',
    options:[{k:'a',t:'Dồn vào sàn, bỏ tạp hoá để đỡ chi phí đội bán hàng'},{k:'b',t:'Xây kênh tạp hoá theo vùng, dùng online làm kênh phụ'},
             {k:'c',t:'Chỉ bán ở siêu thị lớn vì hình ảnh cao cấp hơn'},{k:'d',t:'Đợi đến khi online chiếm 50% ngành mới bắt đầu bán'}],
    answer:'b', why:{a:'Bỏ 90% thị trường để chơi ở 10%.',
      b:'Đúng. Đi theo kênh chính, giữ online để phục vụ đơn lớn và bắt xu hướng.',
      c:'Siêu thị chỉ 30%; bỏ chợ và tạp hoá là mất phần lớn.',
      d:'Chờ đợi không giúp xây kênh nào cả.'} },
  { type:'calc', stem:'Ngành 10.000 tỉ đồng, kênh tạp hoá chiếm 60%. Nếu giành được 2% kênh tạp hoá, doanh số là bao nhiêu tỉ đồng?',
    unit:'tỉ đồng', ans:120, tol:0.5, wrong:[[200,'SAI_MAU_SO'],[1200,'NHAM_DIEM_PHAN_TRAM']], errors:['SAI_MAU_SO'],
    steps:['Kênh tạp hoá: 10.000 × 60% = 6.000 tỉ.','2% × 6.000 = <b>120 tỉ</b>. (200 tỉ là 2% của cả ngành.)'] },
  { type:'mcq', stem:'Vì sao mỹ phẩm chăm sóc da bán online tốt hơn dầu ăn?',
    options:[{k:'a',t:'Vì khách mỹ phẩm thường trẻ hơn và quen mua trên mạng hơn khách dầu ăn'},{k:'b',t:'Vì mỹ phẩm luôn được sàn hỗ trợ phí vận chuyển nhiều hơn'},
             {k:'c',t:'Vì mỹ phẩm không được bán ở tạp hoá và chợ'},{k:'d',t:'Vì nhẹ, giá trị cao, nhiều lựa chọn nên cần xem đánh giá'}],
    answer:'d', why:{a:'Tuổi không phải yếu tố chính; bản chất sản phẩm mới là.',
      b:'Phí ship không phải điểm khác chính; sản phẩm nhẹ, giá trị cao mới là lý do.',
      c:'Mỹ phẩm vẫn bán ở nhiều cửa hàng.',
      d:'Đúng. Phí giao nhỏ so với giá trị, và online giúp so sánh, đọc đánh giá.'} },
  { type:'mcq', stem:'Tình huống mới: một hãng nồi cơm điện thấy 40% doanh số ngành đến từ chuỗi điện máy. Hãng chỉ bán trên trang web riêng. Rủi ro là gì?',
    options:[{k:'a',t:'Bỏ lỡ nơi nhiều khách muốn xem tận tay trước khi mua'},{k:'b',t:'Trang riêng thường bị khách đánh giá thấp hơn sàn'},
             {k:'c',t:'Chuỗi điện máy sẽ kiện vì hãng không bán qua họ'},{k:'d',t:'Trang riêng giữ được lãi cao nên bù phần đơn bị mất'}],
    answer:'a', why:{a:'Đúng. Đồ gia dụng mua cân nhắc, khách muốn xem, sờ, hỏi nhân viên.',
      b:'Đánh giá tuỳ trải nghiệm; rủi ro chính là vắng mặt ở kênh chiếm 40% doanh số.',
      c:'Không có căn cứ pháp lý.',
      d:'Giữ lãi trên đơn ít ỏi không bằng lãi từ kênh lớn.'} },
  { type:'mcq', stem:'Dữ kiện nào cho biết kênh chính của một ngành?',
    options:[{k:'a',t:'Kênh nào đang được báo chí nói đến nhiều nhất'},{k:'b',t:'Kênh mà hãng dẫn đầu đăng bài nhiều nhất'},
             {k:'c',t:'Tỉ trọng doanh số ngành theo từng kênh bán'},{k:'d',t:'Kênh có phí quảng cáo rẻ nhất trong năm'}],
    answer:'c', why:{a:'Được nói nhiều không có nghĩa bán nhiều.',
      b:'Đăng bài là truyền thông, không phải nơi bán.',
      c:'Đúng. Tỉ trọng doanh số cho biết khách thực sự mua ở đâu.',
      d:'Rẻ quảng cáo không có nghĩa là khách mua ở đó.'} },
  { type:'mcq', stem:'Một sàn bắt đầu giao hàng trong 2 giờ ở nội thành. Bạn muốn biết kênh chính của dầu ăn có đang dịch chuyển không. Chỉ báo nào đáng tin nhất?',
    options:[{k:'a',t:'Số lượt xem sản phẩm dầu ăn trên sàn trong đợt khuyến mãi lớn nhất năm'},{k:'b',t:'Số phần trăm doanh số dầu ăn theo kênh nội thành, so với cùng kỳ năm trước'},
             {k:'c',t:'Số bài báo nói về xu hướng mua thực phẩm online trong quý này'},{k:'d',t:'Số người theo dõi trang của hãng dầu ăn đối thủ trên sàn'}],
    answer:'b', why:{a:'Lượt xem trong một đợt khuyến mãi là sự quan tâm ngắn hạn, không phải khách đã chuyển chỗ mua.',
      b:'Đúng. Chỉ có tỉ trọng doanh số theo kênh, theo dõi qua các kỳ, cho biết khách thật sự đổi chỗ mua hay chưa.',
      c:'Bài báo phản ánh điều được bàn tới, không phải điều khách làm.',
      d:'Người theo dõi là truyền thông, không phải nơi khách mua.'} },
  ]},

/* ------------------------------------------------------------------ 09 */
{ id:'B:ob03-09', skill:'insight', read:'7 phút', t:'Vì sao ngành trông dễ làm nhưng người mới hay thua?',
  situation:'Một người bạn muốn làm hãng nước giặt riêng: "Công thức đơn giản, thuê gia công chỉ 15.000 đồng một can, bán 60.000 đồng là lãi to." Bạn hỏi thêm và biết: để vào một chuỗi siêu thị phải trả phí mở mã hàng và chiết khấu cho nhà bán lẻ (giả sử, để tính cho bài: khoảng 50 triệu mỗi mã và chiết khấu 25–30%; con số thật khác nhau tuỳ chuỗi và hợp đồng), và các hãng lớn chi hàng trăm tỉ mỗi năm cho quảng cáo và khuyến mãi.',
  concept:{ name:'Rào cản gia nhập ngành',
    body:'<b>Rào cản gia nhập</b> là những thứ khiến người mới khó vào ngành hoặc khó sống sót. Sản xuất dễ không có nghĩa ngành dễ. Porter (1979, Harvard Business Review) xếp mối đe doạ từ người mới vào làm một trong năm lực cạnh tranh của ngành. Các loại hay gặp: <b>phân phối</b> (phí vào kệ, chiết khấu, công nợ), <b>quy mô</b>, <b>thói quen và thương hiệu</b>, <b>giấy phép và tiêu chuẩn</b>, <b>vốn lưu động</b>. Hãy phân loại: phí kệ, vốn lưu động, giấy phép chủ yếu <b>vượt được bằng tiền</b> và thủ tục; thói quen khách và niềm tin thương hiệu cần <b>thời gian</b>, không mua được trong một quý. Đọc rào cản để chọn cửa vào: một kênh, một vùng hoặc một nhóm khách mà rào cản thấp hơn. Online cũng không miễn rào cản: chi phí có khách cao vẫn chặn người mới.' },
  example:'Nước giặt bán 60.000 đồng. Chiết khấu siêu thị 30% = 18.000 đồng. Hãng thu về 42.000 đồng. Trừ gia công 15.000, còn 27.000 đồng mỗi can để trả vận chuyển, khuyến mãi, phí mở mã, quảng cáo và lương. Muốn thu hồi riêng 10 mã hàng × 50 triệu = 500 triệu phí mở mã, cần bán khoảng 18.500 can chỉ để hoà vốn khoản đó. Rào cản thật không ở nhà máy mà ở kệ hàng. Cửa vào hợp lý hơn: bán online trực tiếp cho một nhóm khách cụ thể trước.',
  takeaway:'Sản xuất dễ không có nghĩa ngành dễ; rào cản thường nằm ở kệ, vốn và thói quen.',
  apply:'Chọn một ngành bạn từng nghĩ "dễ làm". Nói trong 60 giây: ba rào cản lớn nhất với người mới là gì?',
  mistakes:['Tính lãi chỉ bằng giá bán trừ giá gia công, quên chiết khấu kênh.','Nghĩ ngành có nhiều hãng nhỏ (rào cản vào thấp) nghĩa là dễ sống sót và có lãi.'],
  q:[
  { type:'mcq', stem:'Đoán trước: rào cản lớn nhất với hãng nước giặt mới là gì?',
    options:[{k:'a',t:'Công thức nước giặt rất khó tự nghiên cứu ra'},{k:'b',t:'Máy móc sản xuất quá đắt, người mới phải vay rất nhiều mới mua được'},
             {k:'c',t:'Khách không có nhu cầu dùng nước giặt nữa'},{k:'d',t:'Phí vào kệ, chiết khấu và chi phí giữ chỗ trên kệ'}],
    answer:'d', why:{a:'Có thể thuê gia công; công thức không phải rào cản chính.',
      b:'Thuê gia công nên không cần máy riêng.',
      c:'Nhu cầu nước giặt vẫn lớn và ổn định.',
      d:'Đúng. Phân phối và chi phí giữ kệ là rào cản thật.'} },
  { type:'mcq', stem:'Bạn của bạn có 1 tỉ vốn và dự định 10 mã hàng. Bạn khuyên nên chọn cửa vào nào?',
    options:[{k:'a',t:'Một nhóm khách cụ thể qua kênh online trực tiếp trước'},{k:'b',t:'Mở mã ở ba chuỗi siêu thị lớn cùng một lúc cho nhanh'},
             {k:'c',t:'Chạy quảng cáo truyền hình để có tiếng ngay tháng đầu'},{k:'d',t:'Giảm giá xuống 30.000 đồng để thắng các hãng lớn'}],
    answer:'a', why:{a:'Đúng. Tránh phí kệ và chiết khấu, kiểm chứng sản phẩm trước khi mở rộng.',
      b:'Giả định 50 triệu mỗi mã: 10 mã × 3 chuỗi = 1,5 tỉ phí mở mã, vượt vốn trước cả khi nhập hàng.',
      c:'1 tỉ không đủ cho quảng cáo truyền hình có tác dụng.',
      d:'Sau chiết khấu và gia công gần như không còn lãi.'} },
  { type:'calc', stem:'Nước giặt bán 60.000 đồng, siêu thị chiết khấu 30%, gia công 15.000 đồng/can. Hãng còn lại bao nhiêu nghìn đồng mỗi can sau chiết khấu và gia công?',
    unit:'nghìn đồng', ans:27, tol:0.1, wrong:[[45,'QUEN_CHI_PHI_BIEN_DOI'],[42,'QUEN_CHI_PHI_BIEN_DOI']], errors:['QUEN_CHI_PHI_BIEN_DOI'],
    steps:['Sau chiết khấu: 60 × (1 − 30%) = 42 nghìn.','Trừ gia công: 42 − 15 = <b>27 nghìn đồng</b>. (45 là quên trừ chiết khấu; 42 là quên trừ gia công.)'] },
  { type:'mcq', stem:'Với 1 tỉ vốn và 12 tháng, rào cản nào của ngành nước giặt bạn vượt được bằng tiền, rào cản nào chỉ vượt được bằng thời gian?',
    options:[{k:'a',t:'Tiền vượt được phí mở mã và vốn lưu động; thói quen khách cần thời gian tích luỹ'},{k:'b',t:'Tiền mua được thói quen của khách bằng quảng cáo dày; phí mở mã mới cần thời gian'},
             {k:'c',t:'Cả phí mở mã lẫn thói quen khách vượt được bằng tiền, chỉ cần chi đủ lớn'},{k:'d',t:'Chỉ giấy phép vượt được bằng tiền; phí kệ và thói quen đều cần thời gian'}],
    answer:'a', why:{a:'Đúng. Phí kệ và vốn nuôi hàng là tiền; trí nhớ và niềm tin của khách chỉ hình thành qua nhiều lần mua lặp lại.',
      b:'Quảng cáo dày tạo nhận biết nhưng không mua được thói quen trong vài tháng; còn phí mở mã là tiền, không chờ thời gian.',
      c:'Chi lớn cũng không rút ngắn được việc khách phải dùng nhiều lần mới đổi hãng.',
      d:'Phí kệ là tiền trả được ngay; giấy phép nước giặt cũng là thủ tục, không phải rào cản duy nhất vượt bằng tiền.'} },
  { type:'mcq', stem:'Tình huống mới: ngành mở quán trà chanh vỉa hè có rất nhiều hãng nhỏ. Điều này nói gì?',
    options:[{k:'a',t:'Ngành này có biên lãi cao nên nhiều người muốn vào'},{k:'b',t:'Rào cản vào thấp, nên dễ vào nhưng cạnh tranh rất gắt'},
             {k:'c',t:'Hãng lớn đã chiếm hết nên người mới chỉ còn quán nhỏ'},{k:'d',t:'Khách của ngành này trung thành rất cao với từng quán'}],
    answer:'b', why:{a:'Nhiều người vào không có nghĩa lãi cao; thường là ngược lại.',
      b:'Đúng. Rào cản thấp nghĩa là người mới liên tục đến và kéo lợi nhuận xuống.',
      c:'Dữ kiện không cho thấy hãng lớn chiếm lĩnh.',
      d:'Nhiều lựa chọn gần nhau thường làm khách dễ đổi quán.'} },
  { type:'mcq', stem:'Vì sao vốn lưu động là rào cản với hãng mới bán qua đại lý?',
    options:[{k:'a',t:'Vì đại lý thường trả tiền trước khi nhận hàng'},{k:'b',t:'Vì ngân hàng không cho vay các hãng hàng tiêu dùng mới thành lập'},
             {k:'c',t:'Vì hàng tiêu dùng để lâu được nên tồn kho ít tốn'},{k:'d',t:'Vì hàng giao trước, tiền thu sau, vốn nằm ở kho và công nợ'}],
    answer:'d', why:{a:'Thường ngược lại: đại lý trả sau.',
      b:'Không có quy định như vậy.',
      c:'Nhiều hàng có hạn dùng, càng làm vốn rủi ro hơn.',
      d:'Đúng. Hãng mới phải có tiền để nuôi hàng và công nợ nhiều tháng.'} },
  { type:'mcq', stem:'Đâu là cách đọc rào cản hữu ích nhất trước khi vào ngành?',
    options:[{k:'a',t:'Chỉ hỏi chi phí sản xuất một đơn vị sản phẩm'},{k:'b',t:'Đếm số lượt tìm kiếm tên ngành trên mạng'},
             {k:'c',t:'Tính các chi phí từ nhà máy đến tay khách'},{k:'d',t:'Xem hãng dẫn đầu có bao nhiêu người theo dõi'}],
    answer:'c', why:{a:'Giá sản xuất chỉ là một phần nhỏ.',
      b:'Lượt tìm cho biết quan tâm, không cho biết rào cản.',
      c:'Đúng. Chiết khấu, vận chuyển, phí kệ, khuyến mãi mới lộ ra rào cản thật.',
      d:'Người theo dõi không phải rào cản chính.'} },
  ]},

/* ------------------------------------------------------------------ 10 */
{ id:'B:ob03-10', skill:'brand', read:'7 phút', t:'Khi luật chơi của ngành đang đổi, bạn đọc dấu hiệu nào?',
  situation:'Bạn làm cho một chuỗi cà phê có 30 cửa hàng lớn, mặt bằng đẹp. Hai năm gần đây, tổng doanh số đi ngang quanh 100 tỉ một năm, trong khi các chuỗi cà phê mang đi ki-ốt nhỏ mở rất nhanh. Số liệu nội bộ cho thấy đơn giao qua ứng dụng tăng từ 15% lên 35% tổng doanh số, và giá trung bình mỗi ly khách chấp nhận đang giảm.',
  concept:{ name:'Ngành đổi luật chơi',
    body:'Luật chơi của ngành đổi khi <b>công nghệ</b>, <b>kênh</b> hoặc <b>thói quen</b> đổi. Ví dụ minh hoạ (xu hướng được bàn nhiều, không dùng làm số liệu): cà phê chuỗi có thể dịch từ "ngồi lại" sang thêm "mang đi, nhanh, rẻ"; mỹ phẩm online đổi từ trang web sang livestream. Dấu hiệu sớm: <b>tỉ trọng kênh dịch chuyển</b>, <b>mô hình mới mở nhanh</b>, <b>giá chấp nhận thay đổi</b>, khách mới đến từ nơi khác. Phân biệt tín hiệu với nhiễu bằng độ bền và độ rộng: dịch chuyển kéo dài nhiều quý, ở nhiều hãng và nhiều khu vực mới đáng tin; một tháng mưa thì không. Đặt ngưỡng hành động trước, ví dụ giao hàng vượt 30% doanh số hai quý liền thì mở ki-ốt thử. Người dẫn đầu cũ thường chậm nhất vì luật cũ đang nuôi họ.' },
  example:'Tổng doanh số quanh 100 tỉ. Doanh thu đơn giao qua app tăng từ 15 tỉ lên 35 tỉ, còn doanh thu khách ngồi tại cửa hàng giảm từ 85 tỉ còn 65 tỉ. Cần tách hai chuyện: đơn giao có thể vẫn do chính 30 cửa hàng thực hiện (chỉ đổi kênh bán), còn luật đổi thật khi khách chọn mang đi, ly nhỏ, giá thấp và ki-ốt mở nhanh quanh bạn. Chuỗi nên đo biên của đơn giao sau phí app và đóng gói, thử 3 ki-ốt gần văn phòng, rồi sau 3 tháng so lãi trên mỗi mét vuông của ki-ốt với cửa hàng lớn.',
  takeaway:'Luật chơi đổi khi kênh, công nghệ hay thói quen đổi; thấy sớm, thử nhỏ, rồi quyết.',
  apply:'Chọn một ngành bạn theo dõi. Nói trong 60 giây: một dấu hiệu cho thấy luật chơi đang đổi, và một thử nghiệm nhỏ bạn sẽ làm.',
  mistakes:['Coi doanh số đi ngang là do mùa hay do kinh tế mà không xem tỉ trọng kênh.','Đổi toàn bộ mô hình ngay mà không thử nhỏ trước.'],
  q:[
  { type:'mcq', stem:'Đoán trước: dấu hiệu nào mạnh nhất cho thấy luật chơi cà phê chuỗi đang đổi?',
    options:[{k:'a',t:'Một tháng doanh số giảm vì mưa nhiều hơn bình thường'},{k:'b',t:'Đối thủ đổi logo và màu sắc cửa hàng mới'},
             {k:'c',t:'Tỉ trọng giao hàng tăng từ 15% lên 35% trong hai năm'},{k:'d',t:'Giá cà phê nguyên liệu trên thị trường thế giới tăng nhẹ trong quý vừa rồi'}],
    answer:'c', why:{a:'Một tháng mưa là biến động ngắn hạn.',
      b:'Đổi logo không thay đổi luật chơi của ngành.',
      c:'Đúng. Kênh dịch chuyển mạnh và kéo dài là dấu hiệu luật đổi.',
      d:'Giá nguyên liệu ảnh hưởng biên, không đổi cách khách mua.'} },
  { type:'mcq', stem:'Chuỗi có 30 cửa hàng lớn. Bạn đề xuất làm gì trước?',
    options:[{k:'a',t:'Đóng cả 30 cửa hàng lớn để chuyển sang ki-ốt ngay'},{k:'b',t:'Giữ nguyên mô hình vì cửa hàng lớn là thế mạnh xưa nay'},
             {k:'c',t:'Giảm giá tất cả ly 30% để kéo khách về cửa hàng'},{k:'d',t:'Thử 3 ki-ốt mang đi và menu riêng cho app trong 3 tháng'}],
    answer:'d', why:{a:'Đổi toàn bộ khi chưa có bằng chứng là rủi ro quá lớn.',
      b:'Bỏ qua dấu hiệu rõ ràng khiến chuỗi tụt lại.',
      c:'Giảm giá không đổi được cách khách muốn mua.',
      d:'Đúng. Thử nhỏ, đo rõ, rồi mới quyết định mở rộng.'} },
  { type:'calc', stem:'Chuỗi doanh thu 100 tỉ/năm. Tỉ trọng tại cửa hàng giảm từ 85% xuống 65%. Doanh thu tại cửa hàng giảm bao nhiêu tỉ đồng (giả sử tổng không đổi)?',
    unit:'tỉ đồng', ans:20, tol:0.1, wrong:[[23.5,'NHAM_DIEM_PHAN_TRAM'],[65,'NHAM_SO_TUYET_DOI']], errors:['NHAM_DIEM_PHAN_TRAM','NHAM_SO_TUYET_DOI'],
    steps:['Trước: 100 × 85% = 85 tỉ. Sau: 100 × 65% = 65 tỉ.','Giảm 85 − 65 = <b>20 tỉ</b>. (23,5 là phần trăm giảm tương đối, không phải số tiền.)'] },
  { type:'mcq', stem:'Vì sao hãng dẫn đầu cũ thường phản ứng chậm khi luật chơi đổi?',
    options:[{k:'a',t:'Vì luật cũ đang nuôi họ, đổi là tự làm hại phần đang có lãi'},{k:'b',t:'Vì họ không có đủ tiền để thử một mô hình kinh doanh mới'},
             {k:'c',t:'Vì pháp luật cấm hãng lớn mở mô hình kinh doanh mới'},{k:'d',t:'Vì khách quen của họ hiếm khi đổi thói quen mua sắm'}],
    answer:'a', why:{a:'Đúng. Mọi quy trình, mặt bằng, chỉ tiêu đều gắn với luật cũ, nên đổi là tốn kém và đau.',
      b:'Hãng lớn thường có nhiều tiền hơn; vấn đề là động lực.',
      c:'Không có quy định như vậy.',
      d:'Khách đang thay đổi, đó chính là vấn đề.'} },
  { type:'mcq', stem:'Tình huống mới: ngành trà sữa, các hãng mới quảng bá "ít đường, trà nguyên lá". Nên đọc tín hiệu này thế nào?',
    options:[{k:'a',t:'Bỏ qua, vì chỉ là chiêu quảng cáo nhất thời của vài hãng mới'},{k:'b',t:'Coi là giả thuyết về tiêu chí chọn mới, kiểm bằng doanh số dòng ít đường'},
             {k:'c',t:'Kết luận ngay là phản ứng với giá đường tăng, vì nhiều hãng cùng đổi'},{k:'d',t:'Kết luận ngay là quy định nhãn mới, vì hãng nào cũng phải tuân theo'}],
    answer:'b', why:{a:'Nhiều hãng cùng làm là tín hiệu cần kiểm chứng, không phải điều để bỏ qua.',
      b:'Đúng. Từ một tín hiệu chưa thể kết luận nguyên nhân; coi là giả thuyết và kiểm bằng doanh số dòng ít đường và hỏi khách.',
      c:'Giá đường là một giả thuyết cạnh tranh hợp lý, nhưng chưa có dữ kiện, nên kết luận ngay là vội.',
      d:'Quy định nhãn cũng là khả năng, nhưng chưa có dữ kiện; nếu có, cả ngành đã đổi đồng loạt chứ không chỉ hãng mới.'} },
  { type:'mcq', stem:'Trong mỹ phẩm online, dấu hiệu nào cho thấy kênh đang đổi?',
    options:[{k:'a',t:'Có thêm một hãng mới đăng ký bán trên sàn'},{k:'b',t:'Một người nổi tiếng đăng bài giới thiệu một lần'},
             {k:'c',t:'Giá sản phẩm tăng nhẹ trong dịp cuối năm'},{k:'d',t:'Tỉ trọng đơn từ livestream tăng đều nhiều quý liền'}],
    answer:'d', why:{a:'Một hãng mới không phải dịch chuyển kênh.',
      b:'Một bài đăng là sự kiện đơn lẻ.',
      c:'Tăng giá theo mùa không phải đổi kênh.',
      d:'Đúng. Xu hướng kéo dài nhiều quý là dấu hiệu kênh đang đổi.'} },
  { type:'mcq', stem:'Sau 3 tháng thử ki-ốt, bạn nên dùng chỉ số nào để quyết định mở rộng?',
    options:[{k:'a',t:'Số lượt thích trang của ki-ốt trên mạng xã hội'},{k:'b',t:'Số nhân viên làm việc tại mỗi ki-ốt mỗi ca'},
             {k:'c',t:'Doanh thu và lãi trên mỗi mét vuông so với cửa hàng lớn'},{k:'d',t:'Số lần tên ki-ốt được báo chí và các trang review đồ uống nhắc đến'}],
    answer:'c', why:{a:'Lượt thích không nói được hiệu quả kinh doanh.',
      b:'Số nhân viên là chi phí, không phải kết quả.',
      c:'Đúng. So cùng thước đo hiệu quả mặt bằng mới cho biết mô hình nào tốt hơn.',
      d:'Được nhắc tên không phải là có lãi.'} },
  ]},

]});
